      "proposed_laureates": [
        "Paul B. Corkum",
        "Maciej Lewenstein"
      ],
      "assessment": {
        "nobel_worthiness": "Electron recollision and its strong-field theory opened a new way to follow and control electronic motion on its natural time scale, with broad impact across atomic and molecular physics.",
        "attribution": "Corkum's recollision picture and Lewenstein's influential quantum model are central contributions; credit should reflect both the physical insight and its theoretical development.",
        "maturity": "The framework has been tested and extended across decades of experiments, including the development of attosecond science.",
        "uncertainties": [
          "The boundary between this contribution and the wider development of high-harmonic and attosecond methods is difficult to draw."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable stringent tests of fundamental physics through exceptionally accurate comparisons of atomic transitions.",
        "attribution": "Katori and Ye independently developed key approaches and demonstrated the field's potential; the paired attribution is well supported.",
        "maturity": "The methods have been repeatedly realized by independent groups, with clock performance and applications advancing over many years.",
        "uncertainties": [
          "The Nobel scope would need to distinguish the core clock innovations from the broader history of optical frequency metrology."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made matter waves into exceptionally sensitive probes of acceleration, rotation, and fundamental interactions, linking quantum coherence to precision measurement.",
        "attribution": "Bordé and Pritchard helped establish foundational methods, while Kasevich led landmark demonstrations and extensions; the credit spans distinct stages of development.",
        "maturity": "The technique has been replicated and diversified across laboratories and measurement targets.",
        "uncertainties": [
          "The long development history makes it hard to identify a small set of contributors without omitting important work."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their theoretical proposals clarified how trapped ions could implement quantum computation and how controlled atoms could simulate quantum many-body systems.",
        "attribution": "Cirac and Zoller are strongly associated with the foundational trapped-ion proposal and a broad body of influential work.",
        "maturity": "Trapped-ion control and quantum simulation have been established experimentally, though scalable, fault-tolerant computation remains unfinished.",
        "uncertainties": [
          "The laureate scope could overlap with other platforms and with broader quantum information contributions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B057",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that fragile quantum information can in principle be protected, a conceptual advance central to quantum information physics.",
        "attribution": "Shor and Steane introduced influential codes, while Kitaev developed topological approaches; these are complementary foundational contributions.",
        "maturity": "Experiments have demonstrated error correction and improving logical qubits, but large-scale fault-tolerant operation is not yet established.",
        "uncertainties": [
          "The field is still developing, and it remains uncertain which approaches will prove most consequential."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Passive femtosecond mode-locking made compact ultrashort-pulse lasers practical and greatly expanded access to ultrafast phenomena.",
        "attribution": "Keller and Sibbett are central to the development and demonstration of key mode-locking approaches; Moulton's laser-medium contribution is also relevant.",
        "maturity": "The technology has been robustly adopted and enabled decades of experiments, including later work in attosecond physics.",
        "uncertainties": [
          "The discovery is partly an enabling technology, and the boundary between the laser advance and subsequent scientific discoveries needs care."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B010",
      "proposed_laureates": [
        "H. Jeff Kimble",
        "Gerhard Rempe",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent interfaces between light and matter established essential methods for transferring and storing quantum information, with implications for quantum networks and tests of quantum physics.",
        "attribution": "Kimble, Rempe, and Lukin made important, partly distinct contributions to cavity-based interfaces, photon-mediated interactions, and quantum memories.",
        "maturity": "The underlying interactions are well demonstrated, while large-scale network operation remains an active research goal.",
        "uncertainties": [
          "The proposed discovery spans several related protocols, and its precise scientific boundary is unclear."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed robust electronic phases protected by topology and reshaped condensed matter physics.",
        "attribution": "Kane and Mele provided seminal theoretical predictions, while Molenkamp's experiments demonstrated the quantum spin Hall effect in a material system.",
        "maturity": "The central phenomena have been observed and the field has grown substantially, though material-specific effects can complicate interpretation.",
        "uncertainties": [
          "The long and distributed history of topological phases makes the boundary of the credited discovery uncertain."
        ]
      }
    }
  ]
